10	function CopyInline({ text }: { text: string }) {
11	  const [copied, setCopied] = useState(false);
12	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
13	
14	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
15	
16	  const handleCopy = async () => {
17	    if (timerRef.current) clearTimeout(timerRef.current);
18	    try { await navigator.clipboard.writeText(text); } catch { /* fallback */ }
19	    setCopied(true);
20	    timerRef.current = setTimeout(() => setCopied(false), 2000);
21	  };
22	  return (
23	    <button
24	      onClick={handleCopy}
25	      className={cn(
26	        "inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-2xs font-medium border transition-all",
27	        copied
28	          ? "bg-green-50 text-green-600 border-green-200"
29	          : "bg-white text-muted-foreground border-border/50 hover:bg-muted/40 hover:text-foreground"
30	      )}
31	    >
32	      {copied ? <><Check className="h-2.5 w-2.5" />Copied</> : <><Copy className="h-2.5 w-2.5" />Copy</>}
33	    </button>
34	  );
35	}
