42	export function FindingCard({ finding, className }: FindingCardProps) {
43	  const [expanded, setExpanded] = useState(!finding.is_premium);
44	
45	  const borderColor = {
46	    critical: "border-l-red-500",
47	    warning: "border-l-amber-500",
48	    info: "border-l-blue-500",
49	    passed: "border-l-green-500",
50	  }[finding.severity];
51	
52	  const content = (
53	    <Card
54	      className={cn(
55	        "border-l-4 border-border/50 shadow-soft transition-shadow hover:shadow-soft-md",
56	        borderColor,
57	        className
58	      )}
59	    >
60	      <CardContent className="p-5">
61	        {/* Header */}
62	        <div className="flex items-start justify-between gap-3">
63	          <div className="flex flex-wrap items-center gap-2">
64	            <SeverityBadge severity={finding.severity} />
65	            <h4 className="text-sm font-semibold text-foreground">{finding.title}</h4>
66	          </div>
67	          <div className="flex items-center gap-1.5 shrink-0">
68	            {/* Effort badge */}
69	            <span className={cn(
70	              "hidden sm:inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
71	              getEffortColor(finding.effort)
72	            )}>
73	              <Zap className="h-2.5 w-2.5" />
74	              {getEffortLabel(finding.effort)}
75	            </span>
76	            {/* Lift badge */}
77	            {finding.estimated_lift && finding.estimated_lift !== "0%" && (
78	              <span className="hidden sm:inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
79	                <TrendingUp className="h-2.5 w-2.5" />
80	                {finding.estimated_lift}
81	              </span>
82	            )}
83	            <button
84	              onClick={() => setExpanded(!expanded)}
85	              className="rounded-md p-1 hover:bg-muted/50 transition-colors"
86	            >
87	              <ChevronDown className={cn(
88	                "h-4 w-4 text-muted-foreground transition-transform duration-200",
89	                expanded && "rotate-180"
90	              )} />
91	            </button>
92	          </div>
93	        </div>
94	
95	        {/* Mobile effort/lift badges */}
96	        <div className="mt-2 flex flex-wrap gap-1.5 sm:hidden">
97	          <span className={cn(
98	            "inline-flex items-center gap-0.5 rounded-full border px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide",
99	            getEffortColor(finding.effort)
100	          )}>
101	            <Zap className="h-2.5 w-2.5" />
102	            {getEffortLabel(finding.effort)}
103	          </span>
104	          {finding.estimated_lift && finding.estimated_lift !== "0%" && (
105	            <span className="inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
106	              <TrendingUp className="h-2.5 w-2.5" />
107	              {finding.estimated_lift}
108	            </span>
109	          )}
110	        </div>
111	
112	        {expanded && (
113	          <div className="mt-4 space-y-4 animate-fade-in">
114	            {/* Current state */}
115	            <div>
116	              <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
117	                What we found
118	              </p>
119	              <div className="rounded-lg bg-muted/40 p-3.5 text-sm text-foreground/80 leading-relaxed">
120	                {finding.current_state}
121	              </div>
122	            </div>
123	
124	            {/* Recommendation */}
125	            <div>
126	              <p className="mb-1.5 text-[11px] font-semibold uppercase tracking-widest text-muted-foreground">
127	                How to fix it
128	              </p>
129	              <p className="text-sm text-foreground leading-relaxed">
130	                {finding.recommendation}
131	              </p>
132	            </div>
133	
134	            {/* AI Suggestion */}
135	            {finding.ai_suggestion && (
136	              <div className="rounded-lg border border-primary/20 bg-primary/[0.03] p-3.5">
137	                <div className="mb-1.5 flex items-center justify-between">
138	                  <div className="flex items-center gap-1.5">
139	                    <Sparkles className="h-3.5 w-3.5 text-primary" />
140	                    <p className="text-[11px] font-semibold uppercase tracking-widest text-primary">AI Suggestion</p>
141	                  </div>
142	                  <CopyInline text={finding.ai_suggestion} />
143	                </div>
144	                <p className="text-sm text-foreground leading-relaxed whitespace-pre-line">
145	                  {finding.ai_suggestion}
146	                </p>
147	              </div>
148	            )}
149	
150	            {/* Meta: category + effort on mobile */}
151	            <div className="flex items-center gap-3 text-[11px] text-muted-foreground">
152	              <span>Category: <span className="font-medium text-foreground">{finding.category}</span></span>
153	              <span>&middot;</span>
154	              <span>Effort: <span className="font-medium text-foreground">{getEffortLabel(finding.effort)}</span></span>
155	              {finding.estimated_lift && finding.estimated_lift !== "0%" && (
156	                <>
157	                  <span>&middot;</span>
158	                  <span>Expected lift: <span className="font-medium text-foreground">{finding.estimated_lift}</span></span>
159	                </>
160	              )}
161	            </div>
162	          </div>
163	        )}
164	      </CardContent>
165	    </Card>
166	  );
167	
168	  if (finding.is_premium) {
169	    return <PremiumLock>{content}</PremiumLock>;
170	  }
171	
172	  return content;
173	}
