1	import { Check, Loader2 } from "lucide-react";
2	import { cn } from "@/lib/utils";
3	import type { ScanStep } from "@/types";
4	
5	interface ScanProgressTimelineProps {
6	  steps: ScanStep[];
7	  currentStep: number; // 0-indexed, -1 means not started
8	  className?: string;
9	}
10	
11	export function ScanProgressTimeline({
12	  steps,
13	  currentStep,
14	  className,
15	}: ScanProgressTimelineProps) {
16	  return (
17	    <div className={cn("space-y-0", className)}>
18	      {steps.map((step, index) => {
19	        const isCompleted = index < currentStep;
20	        const isActive = index === currentStep;
21	        const isPending = index > currentStep;
22	
23	        return (
24	          <div key={index} className="flex gap-4">
25	            {/* Timeline line + circle */}
26	            <div className="flex flex-col items-center">
27	              <div
28	                className={cn(
29	                  "flex h-8 w-8 shrink-0 items-center justify-center rounded-full border-2 transition-all duration-300",
30	                  isCompleted && "border-success bg-success",
31	                  isActive && "border-primary bg-primary animate-pulse-ring",
32	                  isPending && "border-border/50 bg-white"
33	                )}
34	              >
35	                {isCompleted && <Check className="h-4 w-4 text-white" />}
36	                {isActive && <Loader2 className="h-4 w-4 animate-spin text-white" />}
37	                {isPending && (
38	                  <span className="h-2 w-2 rounded-full bg-muted-foreground/30" />
39	                )}
40	              </div>
41	              {/* Connecting line */}
42	              {index < steps.length - 1 && (
43	                <div
44	                  className={cn(
45	                    "w-0.5 flex-1 min-h-[24px] transition-colors duration-300",
46	                    isCompleted ? "bg-success" : "bg-border"
47	                  )}
48	                />
49	              )}
50	            </div>
51	            {/* Step content */}
52	            <div className="pb-6 pt-1">
53	              <p
54	                className={cn(
55	                  "text-sm font-medium transition-colors duration-300",
56	                  isCompleted && "text-success",
57	                  isActive && "text-foreground",
58	                  isPending && "text-muted-foreground"
59	                )}
60	              >
61	                {step.label}
62	                {isCompleted && " — Done"}
63	                {isActive && "..."}
64	              </p>
65	              <p className="mt-0.5 text-xs text-muted-foreground">{step.description}</p>
66	            </div>
67	          </div>
68	        );
69	      })}
70	    </div>
71	  );
72	}
